def total_of_tail(values, k):
    # Handle invalid or out-of-bounds k
    if k <= 0:
        return 0
    if k >= len(values):
        k = len(values)

    # Calculate sum of last k elements
    total = 0
    for i in range(len(values) - k, len(values)):
        total += values[i]

    return total
